import { createServer } from "node:http";
import { createRequire } from "node:module";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
/** Resolve Vite from the project, including for the dependency-free published CLI. */
export async function mountVite(options) {
    const { projectDir, hostname, shared, config } = options;
    let vitePath;
    try {
        vitePath = createRequire(join(projectDir, "package.json")).resolve("vite");
    }
    catch {
        throw new Error(`Could not resolve "vite" from ${projectDir}. Add vite to the project's devDependencies and reinstall.`);
    }
    const vite = (await import(pathToFileURL(vitePath).href));
    // Vite owns upgrade listeners on this unbound server, including across restarts.
    const upgrades = createServer();
    let partialServer;
    const ownership = {
        name: "dev-shell:server-ownership",
        enforce: "pre",
        configureServer: {
            order: "pre",
            handler(server) {
                partialServer = server;
            },
        },
    };
    const transport = {
        name: "dev-shell:shared-listener",
        enforce: "post",
        configResolved(resolved) {
            resolved.server.middlewareMode = { server: upgrades };
            resolved.server.open = false;
            resolved.server.origin = `http://${hostname}:${shared.port}`;
            const ws = {
                server: upgrades,
                host: hostname,
                port: shared.port,
                clientPort: shared.port,
                protocol: "ws",
                path: "/",
            };
            // Each worker uses its own installed Vite version.
            // Older versions configure WebSocket transport through server.hmr.
            // Remove the fallback when we require Vite 8.2 or later in worker projects.
            if ("ws" in resolved.server) {
                resolved.server.ws = ws;
            }
            else {
                resolved.server.hmr = {
                    ...(typeof resolved.server.hmr === "object"
                        ? resolved.server.hmr
                        : {}),
                    ...ws,
                };
            }
        },
    };
    let server;
    try {
        server = await vite.createServer({
            ...config,
            plugins: [ownership, ...(config.plugins ?? []), transport],
        });
    }
    catch (error) {
        try {
            await partialServer?.close();
        }
        finally {
            upgrades.removeAllListeners();
        }
        throw error;
    }
    shared.routes.set(hostname, {
        handle: (req, res) => server.middlewares(req, res),
        upgrades,
    });
    return async () => {
        shared.routes.delete(hostname);
        // Let initial imports settle before Vite cancels dependency discovery.
        // The run's shutdown deadline still bounds this wait.
        await server
            .waitForRequestsIdle()
            .finally(() => server.close())
            .finally(() => upgrades.removeAllListeners());
    };
}
